import{_ as o,C as r,o as n,c as i,j as e,a as d,E as s,a2 as l}from"./chunks/framework.DCaeQ2Kp.js";const T=JSON.parse('{"title":"声线克隆轨道","description":"","frontmatter":{},"headers":[],"relativePath":"guide/voice-clone.md","filePath":"guide/voice-clone.md"}'),c={name:"guide/voice-clone.md"};function h(m,t,b,p,u,_){const a=r("DiagramFrame");return n(),i("div",null,[t[0]||(t[0]=e("h1",{id:"声线克隆轨道",tabindex:"-1"},[d("声线克隆轨道 "),e("a",{class:"header-anchor",href:"#声线克隆轨道","aria-label":'Permalink to "声线克隆轨道"'},"​")],-1)),t[1]||(t[1]=e("p",null,[d("目标：momo 拥有一条稳定、低延迟、有辨识度的克隆声线。"),e("strong",null,"不依赖代码里程碑，素材收集本周即可开始。")],-1)),s(a,{src:"voice-clone.html",height:660}),t[2]||(t[2]=l('<h2 id="素材分级与质量门槛" tabindex="-1">素材分级与质量门槛 <a class="header-anchor" href="#素材分级与质量门槛" aria-label="Permalink to &quot;素材分级与质量门槛&quot;">​</a></h2><table tabindex="0"><thead><tr><th>级别</th><th>时长</th><th>用途</th></tr></thead><tbody><tr><td>T0</td><td>30s-2min</td><td>零样本试听下限</td></tr><tr><td>T1</td><td>2-10min</td><td>优选零样本 / 多参考音轮换</td></tr><tr><td>T2</td><td>10-60min</td><td>SFT 级（CosyVoice3 / GPT-SoVITS）</td></tr></tbody></table><p>每一级都必须：单人声、无 BGM/音效、低底噪、WAV 单声道 ≥24kHz、约 -20~-16 LUFS、覆盖平静/开心/抱怨三类语气。<strong>只克隆有权使用的声音</strong>，授权记录写入 <code>voice-materials/manifest.md</code>。</p><h2 id="基座选择" tabindex="-1">基座选择 <a class="header-anchor" href="#基座选择" aria-label="Permalink to &quot;基座选择&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Fun-CosyVoice3-0.5B（首选）</th><th>GPT-SoVITS（备选）</th><th>IndexTTS-2（评估项）</th></tr></thead><tbody><tr><td>语言</td><td>9 语言含中日英</td><td>中英日韩粤</td><td>中英为主</td></tr><tr><td>流式</td><td>双向流式，标称首包 150ms</td><td>分块输出</td><td>待实测</td></tr><tr><td>情感</td><td>instruct 文本指令</td><td>参考音迁移+文本</td><td>情感向量</td></tr><tr><td>生态</td><td>官方训练脚本</td><td>微调工具链最成熟</td><td>训练链待评估</td></tr></tbody></table><p>选择原则：<strong>盲听说话</strong>——质量并列时按 流式 &gt; 情感控制 &gt; 依赖风险 &gt; 训练支持 排序。</p><h2 id="评估协议" tabindex="-1">评估协议 <a class="header-anchor" href="#评估协议" aria-label="Permalink to &quot;评估协议&quot;">​</a></h2><ul><li>固定 3 段参考音（平静/开心/抱怨）+ 固定 15 句测试集（含 code-switch 混句）</li><li>盲听 A/B：≥2 人、样本乱序去标签、4 维打分（相似度×2 + 自然度 + 情感 + 稳定性）</li><li>达标线：<strong>加权分 ≥3.5 且无任一句 ≤2</strong></li></ul><h2 id="sft-路径-零样本不达标时" tabindex="-1">SFT 路径（零样本不达标时） <a class="header-anchor" href="#sft-路径-零样本不达标时" aria-label="Permalink to &quot;SFT 路径（零样本不达标时）&quot;">​</a></h2><p>VAD 切片 3-10s → 清洗 → SenseVoice 标注 + 人工抽检 ≥10% → 4090D 单卡 ≤24h（checkpoint 每 2h）→ <strong>结束前 ≥1h rsync 回传</strong> → 盲听复测 → <code>MOMO_TTS_MODEL_DIR</code> env 切换灰度上线，N-1 版本保留可回滚。</p><div class="info custom-block"><p class="custom-block-title">权威来源</p><p><a href="https://github.com/Momoyeyu/momo-docs/blob/master/04-tracks/voice-clone.md" target="_blank" rel="noreferrer">momo-docs/04-tracks/voice-clone.md</a> — 完整打分表模板、回传路径、风险对策表。</p></div>',11))])}const f=o(c,[["render",h]]);export{T as __pageData,f as default};
